-- SYS0014 SHEET_COLUMNS (5 sheets / 19 cols)
DELETE FROM SCM_MST_SHEET_COLUMNS WHERE PROGRAM_ID='SYS0014' AND SHEET_NAME='customer';
DELETE FROM SCM_MST_SHEET_COLUMNS WHERE PROGRAM_ID='SYS0014' AND SHEET_NAME='division';
DELETE FROM SCM_MST_SHEET_COLUMNS WHERE PROGRAM_ID='SYS0014' AND SHEET_NAME='main';
DELETE FROM SCM_MST_SHEET_COLUMNS WHERE PROGRAM_ID='SYS0014' AND SHEET_NAME='plant';
DELETE FROM SCM_MST_SHEET_COLUMNS WHERE PROGRAM_ID='SYS0014' AND SHEET_NAME='userInfo';
-- division/plant/customer UNIT_ID 의 lookup combo SQL_ID (INSERT 컬럼 list 에 CELL_COMBO_DATA_TYPE 없어 별도 UPDATE)
UPDATE SCM_MST_SHEET_COLUMNS SET CELL_COMBO_DATA_TYPE='Division'    WHERE PROGRAM_ID='SYS0014' AND SHEET_NAME='division' AND COLUMN_NAME='UNIT_ID';
UPDATE SCM_MST_SHEET_COLUMNS SET CELL_COMBO_DATA_TYPE='SalesPlant'  WHERE PROGRAM_ID='SYS0014' AND SHEET_NAME='plant'    AND COLUMN_NAME='UNIT_ID';
UPDATE SCM_MST_SHEET_COLUMNS SET CELL_COMBO_DATA_TYPE='EndCustomer' WHERE PROGRAM_ID='SYS0014' AND SHEET_NAME='customer' AND COLUMN_NAME='UNIT_ID';
COMMIT;
